package local.proskurnin.preview;
final class WeatherState {
 static final int UNKNOWN=0,CLEAR=1,PARTLY=2,CLOUD=3,FOG=4,DRIZZLE=5,RAIN=6,SNOW=7,ICE=8,STORM=9,HAIL=10,WIND=11,STORM_HAIL=12;
 static int wmo(int c){switch(c){case 0:case 1:return CLEAR;case 2:return PARTLY;case 3:return CLOUD;case 45:case 48:return FOG;case 51:case 53:case 55:return DRIZZLE;case 56:case 57:case 66:case 67:return ICE;case 61:case 63:case 65:case 80:case 81:case 82:return RAIN;case 71:case 73:case 75:case 77:case 85:case 86:return SNOW;case 95:return STORM;case 96:case 99:return STORM_HAIL;default:return UNKNOWN;}}
 static String description(int c){switch(c){case 0:return "Ясно";case 1:return "Преимущественно ясно";case 2:return "Переменная облачность";case 3:return "Облачно";case 45:return "Туман";case 48:return "Ледяной туман";case 51:case 53:case 55:return "Морось";case 56:case 57:return "Переохлаждённая морось";case 61:case 63:return "Дождь";case 65:return "Сильный дождь";case 66:case 67:return "Ледяной дождь";case 71:case 73:return "Снег";case 75:return "Сильный снег";case 77:return "Снежная крупа";case 80:case 81:case 82:return "Ливень";case 85:case 86:return "Снегопад";case 95:return "Гроза";case 96:case 99:return "Гроза с градом";default:return "Состояние неизвестно";}}
 static int wttr(int c){switch(c){case 113:return CLEAR;case 116:return PARTLY;case 119:case 122:return CLOUD;case 143:case 248:case 260:return FOG;case 263:case 266:return DRIZZLE;case 176:case 293:case 296:case 299:case 302:case 305:case 308:case 353:case 356:case 359:return RAIN;case 227:case 230:case 320:case 323:case 326:case 329:case 332:case 335:case 338:case 368:case 371:return SNOW;case 179:case 182:case 185:case 281:case 284:case 311:case 314:case 317:case 362:case 365:return ICE;case 350:case 374:case 377:return HAIL;case 200:case 386:case 389:case 392:case 395:return STORM;default:return UNKNOWN;}}
 static int legacy(String s){s=s.toLowerCase(java.util.Locale.ROOT);if(s.contains("град"))return s.contains("гроз")?STORM_HAIL:HAIL;if(s.contains("гроз"))return STORM;if(s.contains("туман")||s.contains("дымк"))return FOG;if(s.contains("ледян")||s.contains("переохлажд"))return ICE;if(s.contains("снег")||s.contains("снеж"))return SNOW;if(s.contains("морось"))return DRIZZLE;if(s.contains("дожд")||s.contains("ливень"))return RAIN;if(s.contains("переменн")||s.contains("частично"))return PARTLY;if(s.contains("облач")||s.contains("пасмур"))return CLOUD;if(s.contains("ясно")||s.contains("солнеч"))return CLEAR;if(s.contains("ветер"))return WIND;return UNKNOWN;}
}
